import SwiftUI
import AppKit

final class WindowGeometryManager: ObservableObject {

    private enum Mode {
        case main
        case mini
    }

    private weak var window: NSWindow?
    private var observers: [NSObjectProtocol] = []
    private var mode: Mode = .main
    private var originalStyleMask: NSWindow.StyleMask?
    private var originalTitleVisibility: NSWindow.TitleVisibility = .visible
    private var originalTitlebarAppearsTransparent = false
    private var originalMovableByWindowBackground = false

    // Do not let notifications generated by our own window transitions overwrite
    // the independently saved frame for the other mode.
    private var isApplyingProgrammaticFrame = false
    private var frameChangeGeneration = 0

    private let mainFrameKey = "CassettePlayer.MainWindow.Frame"
    private let miniFrameKey = "CassettePlayer.MiniPlayer.Frame"

    func attach(
        _ window: NSWindow,
        alwaysOnTop: Bool
    ) {
        if self.window === window {
            applyWindowLevel(alwaysOnTop: alwaysOnTop)
            return
        }

        removeObservers()
        self.window = window
        mode = .main
        originalStyleMask = window.styleMask
        originalTitleVisibility = window.titleVisibility
        originalTitlebarAppearsTransparent = window.titlebarAppearsTransparent
        originalMovableByWindowBackground = window.isMovableByWindowBackground

        for name in [
            NSWindow.didMoveNotification,
            NSWindow.didResizeNotification
        ] {
            let observer = NotificationCenter.default.addObserver(
                forName: name,
                object: window,
                queue: .main
            ) { [weak self] _ in
                guard let self,
                      !self.isApplyingProgrammaticFrame else {
                    return
                }

                self.saveCurrentFrame()
            }

            observers.append(observer)
        }

        if let savedFrame = storedFrame(for: .main) {
            let restoredFrame = clampedFrame(savedFrame)
            beginProgrammaticFrameChange()
            window.setFrame(restoredFrame, display: true)
            finishProgrammaticFrameChange(after: 0.15)
        } else {
            saveCurrentFrame()
        }

        applyWindowLevel(alwaysOnTop: alwaysOnTop)
    }

    func switchMode(
        toMini: Bool,
        alwaysOnTop: Bool
    ) {
        guard let window else { return }

        let targetMode: Mode = toMini ? .mini : .main

        if isSameMode(targetMode) {
            applyWindowLevel(alwaysOnTop: alwaysOnTop)
            return
        }

        // Save the frame under the OLD mode before changing mode or window style.
        saveCurrentFrame()
        let previousFrame = window.frame

        beginProgrammaticFrameChange()
        mode = targetMode
        applyMiniTitlebarMode(isMini: toMini)

        let targetSize = toMini
            ? NSSize(width: 600, height: 60)
            : NSSize(width: 1024, height: 283)

        var targetFrame: NSRect

        if let savedFrame = storedFrame(for: targetMode) {
            // Restore this mode's own saved position. Mini Player has a fixed size;
            // keep its saved bottom-left origin instead of recalculating its Y.
            targetFrame = savedFrame
            if toMini {
                targetFrame.size = targetSize
            }
        } else {
            // First use of this mode: place it near the previous window.
            window.setContentSize(targetSize)
            targetFrame = window.frame
            targetFrame.origin.x = previousFrame.minX
            targetFrame.origin.y = toMini
                ? previousFrame.maxY - targetFrame.height
                : previousFrame.minY
        }

        // Old saved coordinates can be partly or wholly outside the visible desktop.
        // Clamp the restored frame before showing it.
        targetFrame = clampedFrame(targetFrame)
        window.setFrame(targetFrame, display: true, animate: true)

        applyWindowLevel(alwaysOnTop: alwaysOnTop)
        finishProgrammaticFrameChange(after: 0.65)
    }

    func setAlwaysOnTop(_ enabled: Bool) {
        applyWindowLevel(alwaysOnTop: enabled)
    }

    private func applyMiniTitlebarMode(isMini: Bool) {
        guard let window else { return }

        if isMini {
            // Remove the native title bar and its traffic-light buttons only in Mini Player.
            // The original style is restored when returning to the main player.
            window.styleMask.remove(.titled)
            window.titleVisibility = .hidden
            window.titlebarAppearsTransparent = true
            window.isMovableByWindowBackground = true
        } else {
            if let originalStyleMask {
                window.styleMask = originalStyleMask
            }
            window.titleVisibility = originalTitleVisibility
            window.titlebarAppearsTransparent = originalTitlebarAppearsTransparent
            window.isMovableByWindowBackground = originalMovableByWindowBackground
        }
    }

    private func isSameMode(_ other: Mode) -> Bool {
        switch (mode, other) {
        case (.main, .main), (.mini, .mini):
            return true
        default:
            return false
        }
    }

    private func applyWindowLevel(alwaysOnTop: Bool) {
        guard let window else { return }

        if case .mini = mode, alwaysOnTop {
            window.level = .floating
        } else {
            window.level = .normal
        }
    }

    private func beginProgrammaticFrameChange() {
        frameChangeGeneration += 1
        isApplyingProgrammaticFrame = true
    }

    private func finishProgrammaticFrameChange(after delay: TimeInterval) {
        let generation = frameChangeGeneration

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self,
                  self.frameChangeGeneration == generation else {
                return
            }

            self.isApplyingProgrammaticFrame = false
            self.saveCurrentFrame()
        }
    }

    private func saveCurrentFrame() {
        guard let window else { return }

        let key: String
        switch mode {
        case .main:
            key = mainFrameKey
        case .mini:
            key = miniFrameKey
        }

        UserDefaults.standard.set(
            NSStringFromRect(window.frame),
            forKey: key
        )
    }

    private func storedFrame(for mode: Mode) -> NSRect? {
        let key: String
        switch mode {
        case .main:
            key = mainFrameKey
        case .mini:
            key = miniFrameKey
        }

        guard let value = UserDefaults.standard.string(forKey: key) else {
            return nil
        }

        let frame = NSRectFromString(value)
        guard frame.width > 0, frame.height > 0 else {
            return nil
        }

        return frame
    }

    private func clampedFrame(_ frame: NSRect) -> NSRect {
        let screens = NSScreen.screens
        guard !screens.isEmpty else { return frame }

        // Prefer the screen containing the largest portion of the saved frame.
        let bestScreen = screens.max { lhs, rhs in
            intersectionArea(frame, lhs.visibleFrame)
                < intersectionArea(frame, rhs.visibleFrame)
        }

        let bestArea = bestScreen.map { intersectionArea(frame, $0.visibleFrame) } ?? 0
        let screen: NSScreen
        if bestArea > 0, let bestScreen {
            screen = bestScreen
        } else {
            screen = NSScreen.main ?? screens[0]
        }

        let visible = screen.visibleFrame
        var result = frame

        // Keep the full player visible when the saved coordinates are stale/off-screen.
        result.size.width = min(result.size.width, visible.width)
        result.size.height = min(result.size.height, visible.height)
        result.origin.x = min(
            max(result.origin.x, visible.minX),
            visible.maxX - result.width
        )
        result.origin.y = min(
            max(result.origin.y, visible.minY),
            visible.maxY - result.height
        )

        return result
    }

    private func intersectionArea(_ lhs: NSRect, _ rhs: NSRect) -> CGFloat {
        let intersection = lhs.intersection(rhs)
        guard !intersection.isNull,
              !intersection.isEmpty else {
            return 0
        }

        return intersection.width * intersection.height
    }

    private func removeObservers() {
        for observer in observers {
            NotificationCenter.default.removeObserver(observer)
        }
        observers.removeAll()
    }

    deinit {
        removeObservers()
    }
}

struct WindowAccessor: NSViewRepresentable {

    let onResolve: (NSWindow) -> Void

    func makeNSView(context: Context) -> NSView {
        let view = NSView(frame: .zero)

        DispatchQueue.main.async {
            if let window = view.window {
                onResolve(window)
            }
        }

        return view
    }

    func updateNSView(_ view: NSView, context: Context) {
        DispatchQueue.main.async {
            if let window = view.window {
                onResolve(window)
            }
        }
    }
}
